export type McpAccessibilityConfig = {
  enabled: boolean;
  maxTextChars: number;
  collapseThreshold: number;
  collapseKeepHead: number;
  collapseKeepTail: number;
  minLengthToProcess: number;
};

export const DEFAULT_MCP_ACCESSIBILITY_CONFIG: McpAccessibilityConfig = {
  enabled: true,
  maxTextChars: MCP_ACCESSIBILITY_DEFAULTS.maxTextChars,
  collapseThreshold: MCP_ACCESSIBILITY_DEFAULTS.collapseThreshold,
  collapseKeepHead: MCP_ACCESSIBILITY_DEFAULTS.collapseKeepHead,
  collapseKeepTail: MCP_ACCESSIBILITY_DEFAULTS.collapseKeepTail,
  minLengthToProcess: MCP_ACCESSIBILITY_DEFAULTS.minLengthToProcess,
};

/**
 * Chars `smartFilterText` reserves for the truncation tail/notice (`maxTextChars - this` is the
 * head kept). A `maxTextChars` at or below this leaves no head, so the whole tool result would be
 * replaced by the notice. The engine and the config bounds must agree on this number.
 */
export const MCP_ACCESSIBILITY_TAIL_RESERVE = 300;

/**
 * Minimum sane `maxTextChars`: below this the truncated head is too small to be useful (or empty).
 * Values in `(0, MIN)` are treated as misconfiguration and fall back to the default.
 */
export const MCP_ACCESSIBILITY_MIN_MAX_TEXT_CHARS = MCP_ACCESSIBILITY_TAIL_RESERVE * 2;

function boundedInt(value: unknown, min: number, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) && value >= min
    ? Math.floor(value)
    : fallback;
}

/**
 * Bound a raw/persisted mcpAccessibility config into a safe, fully-populated config. Centralizes
 * the numeric floors so both the DB normalizer and the live MCP-server read path agree (a small
 * `maxTextChars` would otherwise make `smartFilterText` truncate the whole text away).
 */
export function clampMcpAccessibilityConfig(raw: unknown): McpAccessibilityConfig {
  const record = (raw && typeof raw === "object" ? raw : {}) as Record<string, unknown>;
  const d = DEFAULT_MCP_ACCESSIBILITY_CONFIG;
  return {
    enabled: record["enabled"] !== false,
    maxTextChars: boundedInt(record["maxTextChars"], MCP_ACCESSIBILITY_MIN_MAX_TEXT_CHARS, d.maxTextChars),
    collapseThreshold: boundedInt(record["collapseThreshold"], 1, d.collapseThreshold),
    collapseKeepHead: boundedInt(record["collapseKeepHead"], 0, d.collapseKeepHead),
    collapseKeepTail: boundedInt(record["collapseKeepTail"], 0, d.collapseKeepTail),
    minLengthToProcess: boundedInt(record["minLengthToProcess"], 1, d.minLengthToProcess),
  };
}

import { getEncoding, type Tiktoken } from "js-tiktoken";

export type TokenizerEncoding = "cl100k_base" | "o200k_base";

export interface TokenizerContext {
  provider?: string | null;
  model?: string | null;
}

export function tokenizerContextFromBody(body: unknown): TokenizerContext {
  if (!body || typeof body !== "object" || Array.isArray(body)) return {};
  const record = body as Record<string, unknown>;
  return {
    provider: typeof record.provider === "string" ? record.provider : undefined,
    model: typeof record.model === "string" ? record.model : undefined,
  };
}

const encoders = new Map<TokenizerEncoding, Tiktoken>();

function normalize(value: unknown): string {
  return typeof value === "string" ? value.trim().toLowerCase() : "";
}

export function isCodexTokenizerContext(context?: TokenizerContext): boolean {
  const provider = normalize(context?.provider);
  const model = normalize(context?.model);
  return (
    provider === "codex" ||
    provider === "cx" ||
    model.startsWith("codex/") ||
    model.startsWith("cx/") ||
    model.includes("codex")
  );
}

export function resolveTokenizerEncoding(context?: TokenizerContext): TokenizerEncoding {
  return isCodexTokenizerContext(context) ? "o200k_base" : "cl100k_base";
}

function getEncoder(encoding: TokenizerEncoding): Tiktoken {
  const cached = encoders.get(encoding);
  if (cached) return cached;
  const created = getEncoding(encoding);
  encoders.set(encoding, created);
  return created;
}

/**
 * Exact token count for a string using the selected offline tokenizer.
 * Existing callers retain cl100k_base; Codex callers may pass provider/model context
 * to use o200k_base.
 * Defensive: never throws in a counting path — falls back to a char heuristic.
 */
export function countTextTokens(text: string, context?: TokenizerContext): number {
  if (!text || typeof text !== "string") return 0;
  try {
    return getEncoder(resolveTokenizerEncoding(context)).encode(text).length;
  } catch {
    return Math.ceil(text.length / 4);
  }
}

/**
 * ccrQuery.ts — ranged/grep/stats retrieval over a CCR block (pure).
 *
 * `full`/absent → whole text (backward-compat). All modes are fail-safe:
 * incoherent params or an unsafe regex yield { error }, never throw. The grep
 * mode validates the pattern with `safe-regex` (no catastrophic backtracking)
 * before compiling, and bounds matches/pattern length.
 */
import safeRegex from "safe-regex";

export type CcrMode = "full" | "head" | "tail" | "lines" | "grep" | "stats";

export interface CcrQuery {
  mode?: CcrMode;
  n?: number;
  start?: number;
  end?: number;
  pattern?: string;
  unique?: boolean;
}

export type CcrQueryResult = { content: string } | { error: string };

export const MAX_RANGE_LINES = 10_000;
export const MAX_GREP_MATCHES = 1_000;
export const MAX_PATTERN_LEN = 512;

const err = (m: string): CcrQueryResult => ({ error: m });
const ok = (c: string): CcrQueryResult => ({ content: c });

function clampCount(n: number | undefined): number | null {
  if (typeof n !== "number" || !Number.isFinite(n) || n < 1) return null;
  return Math.min(Math.floor(n), MAX_RANGE_LINES);
}

function sliceHead(lines: string[], n: number | undefined): CcrQueryResult {
  const c = clampCount(n);
  if (c === null) return err("head requires a positive 'n'");
  return ok(lines.slice(0, c).join("\n"));
}

function sliceTail(lines: string[], n: number | undefined): CcrQueryResult {
  const c = clampCount(n);
  if (c === null) return err("tail requires a positive 'n'");
  return ok(lines.slice(Math.max(0, lines.length - c)).join("\n"));
}

function sliceLines(lines: string[], start?: number, end?: number): CcrQueryResult {
  if (typeof start !== "number" || typeof end !== "number" || start < 1 || end < 1) {
    return err("lines requires positive 'start' and 'end' (1-indexed)");
  }
  if (start > end) return err("lines: 'start' must be <= 'end'");
  return ok(lines.slice(start - 1, Math.min(end, lines.length)).join("\n"));
}

function grepLines(lines: string[], pattern?: string, unique?: boolean): CcrQueryResult {
  if (!pattern) return err("grep requires a 'pattern'");
  if (pattern.length > MAX_PATTERN_LEN) return err(`pattern exceeds ${MAX_PATTERN_LEN} chars`);
  if (!safeRegex(pattern)) return err("pattern rejected: potentially catastrophic backtracking");
  let re: RegExp;
  try {
    re = new RegExp(pattern);
  } catch {
    return err("invalid regex pattern");
  }
  const matched: string[] = [];
  let truncated = false;
  for (const line of lines) {
    if (re.test(line)) {
      matched.push(line);
      if (matched.length >= MAX_GREP_MATCHES) {
        truncated = true;
        break;
      }
    }
  }
  const out = unique ? [...new Set(matched)] : matched;
  const body = out.join("\n");
  return ok(truncated ? `${body}\n…[truncated at ${MAX_GREP_MATCHES} matches]` : body);
}

function blockStats(text: string, lines: string[]): CcrQueryResult {
  return ok(
    JSON.stringify({
      lines: lines.length,
      chars: text.length,
      bytes: Buffer.byteLength(text, "utf8"),
    })
  );
}

export function queryBlock(text: string, q: CcrQuery): CcrQueryResult {
  const mode = q.mode ?? "full";
  if (mode === "full") return ok(text);
  const lines = text.split("\n");
  switch (mode) {
    case "head":
      return sliceHead(lines, q.n);
    case "tail":
      return sliceTail(lines, q.n);
    case "lines":
      return sliceLines(lines, q.start, q.end);
    case "grep":
      return grepLines(lines, q.pattern, q.unique);
    case "stats":
      return blockStats(text, lines);
    default:
      return err(`unknown mode: ${String(mode)}`);
  }
}

/**
 * CCR retrieve-protocol instruction (#8033)
 *
 * The CCR engine replaces large blocks of text with a bare
 * `[CCR retrieve hash=<24hex> chars=N]` marker (see `index.ts`). A caller that has
 * never been told what that marker means has no way to recover the original
 * content — it can only call `omniroute_ccr_retrieve` if it (a) knows the tool
 * exists and (b) copies the 24-hex hash verbatim.
 *
 * This module injects a single, idempotent `system` message the first time a
 * request carries a CCR marker, teaching the model the marker → tool contract —
 * but ONLY when the caller's advertised `tools[]` proves it can actually reach
 * `omniroute_ccr_retrieve` (an MCP-capable caller). Plain OpenAI-compatible
 * callers that cannot reach the tool must never be told to call it.
 */

const CCR_RETRIEVE_TOOL_NAME = "omniroute_ccr_retrieve";

/** Leading marker that identifies the injected instruction (also the idempotency sentinel). */
export const CCR_PROTOCOL_MARKER_SENTINEL = "[CCR protocol]";

export const CCR_PROTOCOL_INSTRUCTION = `${CCR_PROTOCOL_MARKER_SENTINEL} This conversation uses content-compression-retrieve (CCR). When you see a marker like \`[CCR retrieve hash=<24hex> chars=N]\` in a message, it means the full original text (N characters) was stored and replaced with this marker to save space — call the \`${CCR_RETRIEVE_TOOL_NAME}\` tool with that hash to get the original text back verbatim. Copy the hash EXACTLY as written — all 24 hexadecimal characters, never truncated, abbreviated, or reformatted — a single wrong character will make the retrieval fail. If you instead see a marker like \`[dedup:ref sha=...]\`, it means that content already appeared earlier in this conversation — look back in the message history for it; do NOT call ${CCR_RETRIEVE_TOOL_NAME} for a dedup reference.`;

type ToolLike = {
  type?: unknown;
  name?: unknown;
  function?: { name?: unknown } | null;
};

/**
 * Scan a request body's `tools[]` for the CCR retrieve tool name, across the
 * three shapes seen in the wild: OpenAI-nested (`{type:"function",
 * function:{name}}`), flat (`{name}`), and Claude (`{name}`). A non-array or
 * absent `tools` field means the caller advertised no tools at all → `false`.
 */
export function callerSupportsCcrRetrieve(body: Record<string, unknown>): boolean {
  const tools = body["tools"];
  if (!Array.isArray(tools)) return false;

  return tools.some((tool) => {
    const t = tool as ToolLike;
    const flatName = typeof t?.name === "string" ? t.name : undefined;
    const nestedName = typeof t?.function?.name === "string" ? t.function.name : undefined;
    return flatName === CCR_RETRIEVE_TOOL_NAME || nestedName === CCR_RETRIEVE_TOOL_NAME;
  });
}

type MessageWithContent = {
  role?: unknown;
  content?: unknown;
};

function messageContainsSentinel(message: MessageWithContent): boolean {
  const content = message?.content;
  if (typeof content === "string") return content.includes(CCR_PROTOCOL_MARKER_SENTINEL);
  if (Array.isArray(content)) {
    return content.some(
      (part) =>
        part &&
        typeof part === "object" &&
        typeof (part as Record<string, unknown>)["text"] === "string" &&
        ((part as Record<string, unknown>)["text"] as string).includes(
          CCR_PROTOCOL_MARKER_SENTINEL
        )
    );
  }
  return false;
}

/**
 * Prepend the CCR protocol instruction as a single leading `system` message,
 * but only when:
 *  - the caller can actually reach `omniroute_ccr_retrieve` (see
 *    `callerSupportsCcrRetrieve`), and
 *  - the message history does not already carry the sentinel (idempotent —
 *    multi-turn requests replay prior messages, so without this check the
 *    note would stack once per turn).
 *
 * Otherwise returns `messages` unchanged.
 */
export function injectCcrProtocolInstruction<T extends MessageWithContent>(
  messages: T[],
  body: Record<string, unknown>
): T[] {
  if (!callerSupportsCcrRetrieve(body)) return messages;
  if (messages.some((message) => messageContainsSentinel(message))) return messages;

  const instructionMessage = {
    role: "system",
    content: CCR_PROTOCOL_INSTRUCTION,
  } as unknown as T;

  return [instructionMessage, ...messages];
}
